def initialize_mana(apps,schema_editor):
    Profile=apps.get_model('characters','PlayerProfile')
    Item=apps.get_model('characters','OwnedItem')
    from django.db.models import Sum
    for profile in Profile.objects.using(schema_editor.connection.alias).all().iterator():
        bonus=Item.objects.using(schema_editor.connection.alias).filter(owner_id=profile.pk,is_equipped=True).aggregate(value=Sum('blueprint__mana_bonus'))['value'] or 0
        profile.equipment_mana=bonus;profile.current_mana=profile.mana+bonus
        profile.save(update_fields=['equipment_mana','current_mana'])


